-- AM PAYMENTS_CHECKOUT: ocho revisiones v2 sin publicación; REG_CHK_006 excluida.
-- Base #4528 (puerta REVISION) + #4532 (EKB); juicios del contexto actual, no independientes.
-- No toca legadas, REG_CHK_007, REG_CHK_CUO_003, ni decide comisión/Yape/textos.
BEGIN;
DO $pre$ DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM lf_ops.nucleo_reglas WHERE familia='PAYMENTS_CHECKOUT' AND estado='CANDIDATA';
 IF n<>10 OR (SELECT count(*) FROM lf_ops.reglas)<>586
 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones v
 JOIN lf_ops.nucleo_reglas r ON r.codigo=v.regla
 WHERE r.familia='PAYMENTS_CHECKOUT' AND (v.version<>1 OR v.estado<>'CANDIDATA'))
 OR NOT EXISTS(SELECT 1 FROM public.lf_error_knowledge
 WHERE codigo='LF-NUCLEO-INITIAL-CANDIDATE-REVISION-DEADEND-20261121-001' AND estado='RESUELTO')
 THEN RAISE EXCEPTION 'AM_V2_BASE_DRIFT candidates=% legacy=% bad_versions=% ekb_resuelta=%', n, (SELECT count(*) FROM lf_ops.reglas), (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas r ON r.codigo=v.regla WHERE r.familia='PAYMENTS_CHECKOUT' AND (v.version<>1 OR v.estado<>'CANDIDATA')), (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo='LF-NUCLEO-INITIAL-CANDIDATE-REVISION-DEADEND-20261121-001' AND estado='RESUELTO'); END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo IN('intento_pago_iniciado','reintento_autorizado_backend','datos_pago_backend_verificados','debito_automatico_requerido','peticion_idempotente_equivalente','operacion_es_checkout'))
 THEN RAISE EXCEPTION 'AM_V2_FACT_COLLISION'; END IF;
END $pre$;
-- New pilot facts are explicit logical placeholders; they are not claimed as runtime bindings.
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES
('intento_pago_iniciado','boolean','ninguna','Indica que ya se inició el envío de un intento de pago checkout; hecho lógico del piloto basado en la legada 208, sin binding runtime.'),
('reintento_autorizado_backend','boolean','ninguna','Permiso normalizado del backend para reintentar la misma operación solo con outcome seguro y quote vigente (legadas 208 y 523); hecho lógico piloto sin binding runtime.'),
('datos_pago_backend_verificados','boolean','ninguna','El backend verificó referencia, hora e importes de la operación confirmada (legada 209); hecho lógico del piloto sin binding runtime.'),
('debito_automatico_requerido','boolean','ninguna','El plan de cuotas requiere realmente cobro recurrente automático según política backend vigente; evita exigir consentimiento en modalidad manual; hecho lógico piloto sin binding runtime.'),
('peticion_idempotente_equivalente','boolean','ninguna','Igual operación y payload lógico para la clave idempotente repetida (legada 185); hecho lógico piloto sin binding runtime.'),
('operacion_es_checkout','boolean','ninguna','El request idempotente corresponde al proceso checkout y no al submit de onboarding (legada 185); hecho lógico piloto sin binding runtime.');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen)
SELECT 'PAYMENTS_CHECKOUT',unnest(ARRAY['intento_pago_iniciado','reintento_autorizado_backend','datos_pago_backend_verificados','debito_automatico_requerido','peticion_idempotente_equivalente','operacion_es_checkout']),'CURADO';
DO $am$
DECLARE item jsonb; p jsonb; judge jsonb; proposal jsonb; dry jsonb;
 h1 text; h2 text; code text; v1 record; old_eval jsonb; new_eval jsonb;
 old_snapshot jsonb; old_tests jsonb; old_judges jsonb; previous_legacy_hash text;
 made integer:=0; ok boolean;
BEGIN
 SELECT md5(string_agg(to_jsonb(r)::text,'|' ORDER BY id)) INTO previous_legacy_hash FROM lf_ops.reglas r;
 FOR item IN SELECT value FROM jsonb_array_elements($bundle$[{"codigo":"REG_CHK_002","nota_anterior":72,"hash_v1":"2ac197f1724fae433a6eee38f12046ec635ea0e96e157fd7f75ecd53c9cf9384","motivo_revision":"Acotar cálculo al módulo de pagos sin resolver comisión LF; mejora control de alcance de la regla 156.","patch":{"titulo":"Suma consolidada de importes de ofertas en checkout","alcance":"CLIENT_PAYMENTS","descripcion":"En el resumen de checkout calcular la suma de monto_total de la modalidad elegida por cada oferta seleccionada. La fórmula solo representa importes de ofertas; el precio final y las comisiones se determinan por su configuración vigente y no por esta regla."},"juicio":{"veredicto":"PASS","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"156: cálculo concreto sum(items[].monto_total), resultado observable."},"CAL_ALCANCE":{"puntaje":1,"observacion":"CLIENT_PAYMENTS limita la fórmula al módulo checkout; no se atribuye cobertura del resto de CLIENTE."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto identifica la suma de los importes elegidos."},"COH_EFECTO":{"puntaje":1,"observacion":"CALCULAR coincide con fórmula 156."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"suma de monto_total coincide con valor_config.formula; casos lista con dos montos y vacía."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Consolida únicamente importes de ofertas de 156; no fija comisión ni precio final y coexiste con resumen 155."},"SEM_NO_DUPLICA":{"puntaje":1,"observacion":"El equivalente 156 es la fuente migrada deliberadamente conservada; no hay otra candidata del núcleo con esa clave ni una fórmula distinta en las reglas de la familia revisadas."}}},"referencia_legacy":"lf_ops.reglas/156"},{"codigo":"REG_CHK_004","nota_anterior":67,"hash_v1":"48a5c8e30e3bd1805e0ba392fddc8860a4aa49a82c53855c4166c826f3738f24","motivo_revision":"Incorporar primer intento y autorización backend a la puerta segura de reintento (208,523,228); el binding runtime queda pendiente.","patch":{"titulo":"Reintentos del checkout sometidos a decisión segura del backend","alcance":"CLIENT_PAYMENTS","descripcion":"Tras iniciar el intento de pago, bloquear cualquier reintento mientras el outcome normalizado no sea uno de los estados seguros o el backend no haya autorizado el reintento para la misma operación y quote vigente. Antes del primer intento no se bloquea por esta regla. Un error técnico no equivale a falta de cargo.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"intento_pago_iniciado"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"reintento_autorizado_backend"},"der":{"lit":false}},"der":{"op":"y","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_DECLINED_CONFIRMED"}},"der":{"op":"y","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_NOT_SUBMITTED"}},"der":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_PROVIDER_UNAVAILABLE_BEFORE_SUBMIT"}}}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"reintento_autorizado_backend":false,"estado_pago_normalizado":"PAYMENT_PENDING_CONFIRMATION"},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"reintento_autorizado_backend":true,"estado_pago_normalizado":"PAYMENT_CONFIRMED"},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"reintento_autorizado_backend":false,"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED"},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"reintento_autorizado_backend":true,"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED"},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"reintento_autorizado_backend":true,"estado_pago_normalizado":"PAYMENT_NOT_SUBMITTED"},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"reintento_autorizado_backend":true,"estado_pago_normalizado":"PAYMENT_PROVIDER_UNAVAILABLE_BEFORE_SUBMIT"},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":false,"reintento_autorizado_backend":false,"estado_pago_normalizado":"SIN_INTENTO"},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"208: bloquear CTA para impedir doble submit."},"CAL_ALCANCE":{"puntaje":1,"observacion":"CLIENT_PAYMENTS evita aplicar a home, onboarding o legal."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto identifica bloqueo y resultados que habilitan reintento."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR coincide con bloqueo de CTA."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Añade primer intento y autorización backend y protege outcomes no seguros; falta vincular reintento_autorizado_backend a quote/reserva y operación reales."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"Es compatible con 523 y provider handoff si backend calcula el permiso; hecho lógico aún sin binding runtime."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Coincide parcialmente con REG_CHK_003/provider handoff; no se acredita absorción de todas sus ramas."}}},"referencia_legacy":"lf_ops.reglas/208,523,228"},{"codigo":"REG_CHK_005","nota_anterior":62,"hash_v1":"4794f7c96d6cf3bc051689dd0c753120eba2a09098932a651369d5d7c252e486","motivo_revision":"Separar vista de éxito PANTALLA-33 de los efectos backend por deuda de 209/524; no atribuir cobertura posterior no implementada.","patch":{"titulo":"Pantalla de éxito solo con pago confirmado y datos verificados","alcance":"PANTALLA-33","descripcion":"En CHECKOUT_PAGO_EXITOSO se permite mostrar éxito solo si el backend normalizó PAYMENT_CONFIRMED y verificó referencia, fecha/hora e importes de la operación. Esta regla no ejecuta efectos por deuda, no modifica onboarding_completed ni habilita Carta de No Adeudo por el pago inicial: esos efectos permanecen sujetos a REG_CLIENT_PAYMENT_CONFIRMED_POST_ACTIONS_001.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_CONFIRMED"}},"der":{"op":"=","izq":{"hecho":"datos_pago_backend_verificados"},"der":{"lit":true}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_CONFIRMED","datos_pago_backend_verificados":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_CONFIRMED","datos_pago_backend_verificados":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_PENDING_CONFIRMATION","datos_pago_backend_verificados":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED","datos_pago_backend_verificados":true},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"209/524: permite acciones solo tras confirmación."},"CAL_ALCANCE":{"puntaje":1,"observacion":"PANTALLA-33 es CHECKOUT_PAGO_EXITOSO verificada en árbol de alcance; deja backend por deuda fuera de esta vista."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Define pantalla de éxito, outcome y datos del backend sin prometer activación del plan."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR condicionado a PAYMENT_CONFIRMED expresa el permiso inicial."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"El permiso de render requiere PAYMENT_CONFIRMED y datos de la operación verificados; no ejecuta post-actions."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No muta onboarding ni emite carta; 524 y reglas de plan quedan con el backend."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Sigue solapándose con REG_CLIENT_PAYMENT_SUCCESS_VIEW_001; falta una consolidación formal para habilitar publicación."}}},"referencia_legacy":"lf_ops.reglas/209,524"},{"codigo":"REG_CHK_008","nota_anterior":62,"hash_v1":"355ba0525b769486fd5b234a002259355d5c8f5cf3312de56bd2c745e8033756","motivo_revision":"Separar elegibilidad para solicitar Carta por deuda del ciclo documental y descarga AVAILABLE en fuentes 212,280,292,327.","patch":{"titulo":"Solicitud de carta condicionada a liquidación de cada deuda","alcance":"CLIENT_PAYMENTS","descripcion":"Para cada deuda individual incluida en el checkout, permitir solicitar la Carta de No Adeudo solo al constar SETTLED_CONFIRMED como liquidación total autoritativa. Un pago inicial de cuotas no equivale a liquidación. La emisión y descarga necesitan su propio estado documental; AVAILABLE es requisito adicional de descarga y no se autoriza aquí.","pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"SETTLED_CONFIRMED"},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"PLAN_ACTIVO"},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"PAYMENT_PENDING_CONFIRMATION"},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"212/280/292/327: diferir solicitud hasta liquidación total."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"CLIENT_PAYMENTS restringe la experiencia de pagos, pero la liquidación y documento siguen gobernados por deuda en backend."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El requisito de SETTLED_CONFIRMED es explícito."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR solicitud cuando la deuda está liquidada coincide con elegibilidad."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Condición solo decide elegibilidad de solicitud con estado SETTLED_CONFIRMED, no confunde descarga AVAILABLE ni emisión."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Coherente con no emitir carta por pago inicial y con estados del documento regulados aparte."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"REG_CLIENT_NO_DEBT_LETTER_STATUS_001 ya cubre elegibilidad; pendiente reconciliación de propiedad semántica."}}},"referencia_legacy":"lf_ops.reglas/212,280,292,327"},{"codigo":"REG_CHK_013","nota_anterior":57,"hash_v1":"af6ecc44436e1c2240d29b968a576d806382d05b039f2422c0255e2ebf1e4905","motivo_revision":"Respetar cuota manual frente a cuota con débito automático conforme a consentimiento contextual vigente, 276/288.","patch":{"titulo":"Consentimiento obligatorio solo para cuotas con cobro automático","alcance":"PANTALLA-21","descripcion":"En CHECKOUT_CUOTAS_MEDIO_PAGO bloquear el botón solo si el backend indicó que el plan requiere débito recurrente automático y el usuario no autorizó ese cobro. No exigir la autorización de débito automático cuando el plan de cuotas sea de cobro manual. El consentimiento debe ser explícito.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"modalidad_pago"},"der":{"lit":"CUOTAS"}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"debito_automatico_requerido"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"autoriza_debito_automatico"},"der":{"lit":false}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","debito_automatico_requerido":true,"autoriza_debito_automatico":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","debito_automatico_requerido":true,"autoriza_debito_automatico":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","debito_automatico_requerido":false,"autoriza_debito_automatico":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"PAGO_UNICO","debito_automatico_requerido":false,"autoriza_debito_automatico":false},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"276/288: bloquear CTA sin consentimiento."},"CAL_ALCANCE":{"puntaje":1,"observacion":"PANTALLA-21 corresponde a CHECKOUT_CUOTAS_MEDIO_PAGO; no hereda a otros flujos."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto comunica el requisito, aunque lo generaliza."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR cuando falta autorización coincide con el texto histórico."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Condición incluye necesidad real de débito automático y consentimiento ausente; prueba cuota manual sin bloqueo."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No exige consentimiento en cuotas manuales, conforme a AUTODEBIT_CONSENT_CONTEXT_001 vigente."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"AUTODEBIT_CONSENT_CONTEXT_001 mantiene el mismo ámbito funcional; requiere consolidación antes de publicar."}}},"referencia_legacy":"lf_ops.reglas/276,288"},{"codigo":"REG_TEC_007","nota_anterior":63,"hash_v1":"d2292549f9ff4c08e5b777f8a660e26335a025db11292d4eceda79a4d8951a1f","motivo_revision":"Acotar offline a fase de confirmación checkout; onboarding sigue en 183 y posible envío se concilia con 523.","patch":{"titulo":"No iniciar un pago sin conexión en el checkout","alcance":"CLIENT_PAYMENTS","descripcion":"Durante la confirmación de checkout, si falta conexión, bloquear el envío de un nuevo pago y mostrar un aviso de conexión requerida, conservando la selección. Si un intento pudo haber llegado al proveedor, se debe reconciliar como PAYMENT_PENDING_CONFIRMATION, nunca presumir ausencia de cargo. La conservación local del onboarding permanece en la regla legada y no se considera absorbida aquí.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"checkout_en_confirmacion"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"conexion_disponible"},"der":{"lit":false}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"checkout_en_confirmacion":true,"conexion_disponible":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"checkout_en_confirmacion":true,"conexion_disponible":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"checkout_en_confirmacion":false,"conexion_disponible":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"checkout_en_confirmacion":false,"conexion_disponible":true},"esperado":false}]},"juicio":{"veredicto":"PASS","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"183: bloquear pago y avisar falta de conexión."},"CAL_ALCANCE":{"puntaje":1,"observacion":"CLIENT_PAYMENTS más hecho checkout_en_confirmacion evita invadir onboarding de 183."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto identifica la pérdida de conexión y respuesta de checkout."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR expresa solo impedir un nuevo envío; aviso y conservación no se acreditan como efectos automáticos."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Fase de confirmación y conexión ausente expresan con precisión la prohibición de iniciar nuevo pago offline."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No presume no cargo si el envío ya pudo alcanzar proveedor; convivencia explícita con reconciliación 523."},"SEM_NO_DUPLICA":{"puntaje":1,"observacion":"183 es la fuente declarada; no se detectó otro control idéntico de conectividad, aunque los deberes de reconciliación son complementarios."}}},"referencia_legacy":"lf_ops.reglas/183"},{"codigo":"REG_TEC_009","nota_anterior":62,"hash_v1":"641183a37ee4e75b4d817e8e904a4d4ee76b5e65d6d26733a5fe2f5e460681c0","motivo_revision":"Cambiar RECHAZAR por PERMITIR respuesta anterior; delimitar equivalencia y checkout según 185, sin generar cobro duplicado.","patch":{"titulo":"Reutilizar resultado de una petición idempotente equivalente","alcance":"BACKEND","efecto":"PERMITIR","descripcion":"Solo en una petición de checkout equivalente que repita una clave de idempotencia todavía válida según AUTH/IDEMPOTENCY_KEY_VALIDITY_MINUTES, permitir al backend devolver el resultado existente (confirmado o pendiente) sin crear otra operación ni cobrar de nuevo. Este permiso es reutilización de respuesta, no autorización de un segundo procesamiento. El submit de onboarding Paso 1 sigue cubierto por la regla legada.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"operacion_es_checkout"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"clave_idempotencia_repetida"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"peticion_idempotente_equivalente"},"der":{"lit":true}},"der":{"op":"<","izq":{"hecho":"edad_clave_idempotencia"},"der":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES"}}}}},"pruebas":[{"casuistica":"BAJO_EL_LIMITE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":true},{"casuistica":"EN_EL_LIMITE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES"}},"esperado":false},{"casuistica":"SOBRE_EL_LIMITE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":1}},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":false,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"operacion_es_checkout":false,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"185: devolver resultado anterior sin duplicados."},"CAL_ALCANCE":{"puntaje":1,"observacion":"operacion_es_checkout limita la regla a checkout aunque el nodo técnico sea BACKEND."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Describe reenvío con clave y ventana configurada."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR describe reutilizar la respuesta anterior, no generar otra operación, frente al antiguo RECHAZAR."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Añade equivalencia y contexto de operación; el borde exacto de ventana (<) aún no está explicado por la fuente legada 185."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Evita rechazo indiscriminado y permite devolver resultado pendiente o exitoso; el onboarding sigue en 185."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Las reglas B2B de idempotencia y ONB003 son análogas; falta prueba de integración backend sin repetir el control."}}},"referencia_legacy":"lf_ops.reglas/185"},{"codigo":"REG_CLIENT_CHECKOUT_QR_CONFIRMATION_001","nota_anterior":63,"hash_v1":"f9f81d68d81212a53c2801695f06e939db8a6468c230ab7d2a2956b2e30fcc77","motivo_revision":"Acotar a PANTALLA-28 y bloqueo de confirmación sin evidencia; backend mantiene referencia y vencimiento según 539/316.","patch":{"titulo":"Sin evidencia autoritativa no confirmar pago por QR","alcance":"PANTALLA-28","descripcion":"En CHECKOUT_ESTADO_YAPE_QR bloquear exclusivamente el cambio a PAYMENT_CONFIRMED si falta evidencia autoritativa del proveedor para la operación QR. El CTA Ya escaneé o Continuar solicita consulta o conciliación de la misma referencia: no certifica pago, no crea otra operación y no permite reutilizar un QR vencido. La comprobación de referencia, expiración y resultado terminal corresponde al backend regulado por la regla legada 539.","pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":true},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"539/316: verificar mismo QR sin inventar confirmación."},"CAL_ALCANCE":{"puntaje":1,"observacion":"PANTALLA-28 corresponde exactamente a CHECKOUT_ESTADO_YAPE_QR."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto distingue consulta y confirmación de pago."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR se limita a confirmar como pagado sin evidencia, no impide consultar estado mediante el CTA."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"La condición cubre evidencia autoritativa ausente en pantalla QR; no modela reutilización de referencia ni expiración, delegadas a 539."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"El botón consulta backend y no crea intento nuevo; compatible con outcome normalization 523/539."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"La legada 539 tiene la misma regla migrada; falta comprobar consolidación de consulta y estados terminales."}}},"referencia_legacy":"lf_ops.reglas/539,316"}]$bundle$::jsonb) LOOP
  code:=item->>'codigo';
  SELECT * INTO v1 FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=1 AND estado='CANDIDATA';
  IF v1.version IS NULL OR v1.hash IS DISTINCT FROM item->>'hash_v1'
  THEN RAISE EXCEPTION 'AM_V2_OLD_HASH_DRIFT %',code; END IF;
  old_snapshot:=to_jsonb(v1);
  SELECT jsonb_agg(to_jsonb(t) ORDER BY n) INTO old_tests FROM lf_ops.nucleo_regla_pruebas t WHERE regla=code AND version=1;
  SELECT jsonb_agg(to_jsonb(jj) ORDER BY id) INTO old_judges FROM lf_ops.nucleo_juicios jj WHERE regla=code AND version=1;
  old_eval:=lf_ops.nucleo_regla_evaluar_v1(code,false);
  IF (old_eval->>'nota')::integer IS DISTINCT FROM (item->>'nota_anterior')::integer
     OR old_eval->>'decision'<>'DEVUELTA' THEN
   RAISE EXCEPTION 'AM_V2_OLD_SCORE_DRIFT % %',code,old_eval;
  END IF;
  SELECT jsonb_agg(jsonb_build_object('casuistica',casuistica,'entrada',entrada,'esperado',esperado) ORDER BY n)
   INTO p FROM lf_ops.nucleo_regla_pruebas WHERE regla=code AND version=1;
  proposal:=v1.ficha || jsonb_build_object('pruebas',p) || item->'patch' ||
   jsonb_build_object('tipo','REVISION','version_anterior',1,'hash_anterior',v1.hash,'motivo_revision',item->>'motivo_revision');
  -- No new product decisions: preserve original origin and authority.
  IF proposal->'origen' IS DISTINCT FROM v1.origen
   OR proposal->>'autoridad' IS DISTINCT FROM v1.autoridad
   OR proposal->>'codigo' IS DISTINCT FROM code
  THEN RAISE EXCEPTION 'AM_V2_ORIGIN_OR_AUTHORITY_DRIFT %',code; END IF;
  dry:=lf_ops.nucleo_regla_proponer_v1(proposal,false);
  IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::integer<>0
  THEN RAISE EXCEPTION 'AM_V2_PREFLIGHT_REJECTED % %',code,dry; END IF;
  p:=lf_ops.nucleo_regla_proponer_v1(proposal,true);
  IF p->>'resultado'<>'CANDIDATA' OR (p->>'version')::integer<>2
  THEN RAISE EXCEPTION 'AM_V2_DOOR_FAILED % %',code,p; END IF;
  IF (SELECT to_jsonb(v)-'estado' FROM lf_ops.nucleo_regla_versiones v WHERE regla=code AND version=1)
    IS DISTINCT FROM old_snapshot-'estado'
   OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY n) FROM lf_ops.nucleo_regla_pruebas t WHERE regla=code AND version=1)
    IS DISTINCT FROM old_tests
   OR (SELECT jsonb_agg(to_jsonb(jj) ORDER BY id) FROM lf_ops.nucleo_juicios jj WHERE regla=code AND version=1)
    IS DISTINCT FROM old_judges
   OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=1)<>'DESCARTADA'
   OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=2)<>'CANDIDATA'
  THEN RAISE EXCEPTION 'AM_V2_HISTORY_MUTATED %',code; END IF;
  IF (SELECT jsonb_agg(jsonb_build_object('casuistica',casuistica,'entrada',entrada,'esperado',esperado) ORDER BY n)
    FROM lf_ops.nucleo_regla_pruebas WHERE regla=code AND version=2) IS DISTINCT FROM proposal->'pruebas'
  THEN RAISE EXCEPTION 'AM_V2_TESTS_NOT_COPIED %',code; END IF;
  h2:=lf_ops.nucleo_hash_paquete_v1(code,2);
  IF h2 IS NULL OR h2=lf_ops.nucleo_hash_paquete_v1(code,1)
  THEN RAISE EXCEPTION 'AM_V2_PACKAGE_HASH_NOT_NEW %',code; END IF;
  judge:=item->'juicio'||jsonb_build_object('regla',code,'hash_evaluado',h2,
   'evidencia_ref','https://github.com/cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/nucleo_ci/checkout_am_revisiones_v2.json#'||code);
  -- Negative: wrong hash must fail at its intended guard.
  BEGIN
   PERFORM lf_ops.nucleo_juicio_registrar_v1(judge||jsonb_build_object('hash_evaluado',repeat('0',64)));
   RAISE EXCEPTION 'AM_V2_BAD_HASH_ACCEPTED %',code;
  EXCEPTION WHEN others THEN
   IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
  END;
  PERFORM lf_ops.nucleo_juicio_registrar_v1(judge);
  new_eval:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF new_eval->>'decision' NOT IN ('AUTO','MANUAL','DEVUELTA')
   OR (judge->>'veredicto'='DEVOLVER' AND new_eval->>'decision'<>'DEVUELTA')
  THEN RAISE EXCEPTION 'AM_V2_UNEXPECTED_EVALUATION % %',code,new_eval; END IF;
  -- Negative: a score is not permission for direct publication.
  BEGIN
   PERFORM lf_ops.nucleo_version_publicar_v1(code,2);
   RAISE EXCEPTION 'AM_V2_DIRECT_PUBLICATION_ACCEPTED %',code;
  EXCEPTION WHEN others THEN
   IF SQLERRM NOT LIKE 'NUCLEO_PUBLICAR_SIN_PROMOCION:%' THEN RAISE; END IF;
  END;
  p:=lf_ops.nucleo_regla_proponer_v1(proposal,false);
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'controles') x
   WHERE x->>'n'='0' AND x->>'detalle'='REVISION_VERSION_OBSOLETA' AND (x->>'ok')::boolean=false)
  THEN RAISE EXCEPTION 'AM_V2_REPLAY_GUARD_FAILED % %',code,p; END IF;
  RAISE NOTICE 'AM_V2_RESULT %',jsonb_build_object('codigo',code,'v1_nota',old_eval->'nota','v1_decision',old_eval->>'decision',
    'v2_nota',new_eval->'nota','v2_decision',new_eval->>'decision','v2_version',2,'hash_v2',h2,
    'juez',judge->>'juez','veredicto',judge->>'veredicto','motivos',new_eval->'motivos','componentes',new_eval->'componentes');
  made:=made+1;
 END LOOP;
 IF made<>8 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas n ON n.codigo=v.regla
 WHERE n.familia='PAYMENTS_CHECKOUT' AND v.version=2 AND v.estado='CANDIDATA')<>8
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas n ON n.codigo=v.regla
 WHERE n.familia='PAYMENTS_CHECKOUT' AND v.version=1 AND v.estado='DESCARTADA')<>8
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas n ON n.codigo=v.regla
 WHERE n.familia='PAYMENTS_CHECKOUT' AND v.estado='PUBLICADA')<>0
 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE familia='PAYMENTS_CHECKOUT' AND estado='CANDIDATA')<>10
 OR (SELECT count(*) FROM lf_ops.reglas)<>586
 OR (SELECT md5(string_agg(to_jsonb(r)::text,'|' ORDER BY id)) FROM lf_ops.reglas r) IS DISTINCT FROM previous_legacy_hash
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla IN('REG_CHK_006','REG_CHK_007') AND version=1 AND estado='CANDIDATA')<>2
 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_CUO_003')
 OR EXISTS(SELECT * FROM lf_ops.reglas EXCEPT ALL SELECT * FROM lf_ops.v_reglas_compat_v1 WHERE id IS NOT NULL)
 OR EXISTS(SELECT * FROM lf_ops.v_reglas_compat_v1 WHERE id IS NOT NULL EXCEPT ALL SELECT * FROM lf_ops.reglas)
 THEN RAISE EXCEPTION 'AM_V2_POSTREADBACK_FAILED'; END IF;
 RAISE NOTICE 'AM_V2_PASS 8/8 revisions, 8/8 judgements, zero publications, all 586 legacy identical';
END $am$;
COMMIT;
